    // Step 9: Add AI label
    try {
        tracker.addLabel(ticketKey, LABELS.AI_TEST_AUTOMATION);
    } catch (e) {
        console.warn('Failed to add AI label:', e);
    }

    removeWipLabel(params, ticketKey);
    removeSMTriggerLabel(params, ticketKey);
}

