        assert.deepEqual(reads, ['pr_feature_update.md', 'pr_body.md']);
    });

    test('returns null when neither file exists', function() {
        var h = loadMobileHelpers();
        assert.equal(h.resolveFeatureSummary(function() { return null; }), null);
    });

});

