suite('postMobileTestAutomationResults: tracker layer (ADO)', function() {    test('ado: error path uses ado_* tools and no jira_* tool', function() {
        var calls = [];
        var mocks = {
            file_read: function() { return null; },
            cli_execute_command: function() { throw new Error('boom'); }
        };
        ['jira_post_comment', 'jira_move_to_status', 'jira_add_label', 'jira_remove_label'].forEach(function(n) {
